/** Makes the title button open the switcher; current is the id of the game on screen. */
// Settings, at the top right of the games screen (a gear in Codex, sliders in the other themes): the theme (Deco, Modern,
// Kontor or Office; each with a day and a night that follow the system).
// The choice lives on this device and applies at once, here and on every page (theme.js reads it before drawing).
const THEMES = [["deco", "Codex"], ["modern", "Modern"], ["kontor", "Kontor"], ["office", "Office"]];
const MODES = [["auto", "Auto"], ["day", "Day"], ["night", "Night"]];
export const theme = () => document.documentElement.dataset.theme || "deco";
const mode = () => document.documentElement.dataset.mode || "auto";
// The banner under the head (Deck, Random, Choose) can be put away in Settings (on this device; on at first)
const BANNER = "suite:banner";
const bannerOn = () => { try { return localStorage.getItem(BANNER) !== "off"; } catch { return true; } };
/** Keeps a look on this device and redraws the page in it (the logos and the menu button are the theme's own). */
function keep(key, value, fallback) {
  try { if (value === fallback) localStorage.removeItem(key); else localStorage.setItem(key, value); } catch { /* private mode */ }
  try { sessionStorage.setItem("crates:games", "1"); } catch { /* private mode */ }   // come back to the games screen
  location.reload();
}
function openSettings(host) {
  let sheet = host.querySelector("dialog.apps-settings");
  if (!sheet) {
    sheet = document.createElement("dialog");
    sheet.className = "apps-pop apps-settings";
    sheet.setAttribute("aria-label", "Settings");
    sheet.innerHTML = `<div class="pick-head"><h2>Settings</h2><button class="icon-btn" type="button" data-close aria-label="Close">${ICON.close}</button></div><div class="settings-body"></div>`;
    sheet.querySelector("[data-close]").addEventListener("click", () => sheet.close());
    sheet.addEventListener("click", e => { if (e.target === sheet) sheet.close(); });
    host.appendChild(sheet);
  }
  sheet.querySelector(".settings-body").replaceChildren(
    choice("Theme", THEMES, theme(), t => keep("suite:theme", t, "deco")),
    choice("Appearance", MODES, mode(), m => keep("suite:mode", m, "auto")),
    toggle("Deck and Random on this screen", bannerOn(), on => {
      try { if (on) localStorage.removeItem(BANNER); else localStorage.setItem(BANNER, "off"); } catch { /* private mode */ }
      host.querySelector("[data-rows]")?.toggleAttribute("hidden", !on);      // at once, nothing to reload
    }),
    topicsPart(),
    picturesPart(sheet),
    startOver());
  sheet.showModal();
}
/** Settings' Topics: which subjects every knowledge game deals from (topics.js), set once here, not in each game. */
function topicsPart() {
  const box = document.createElement("section"), head = document.createElement("h4");
  head.className = "menu-h";
  head.textContent = "Topics";
  box.append(head, topicsControls());
  return box;
}
/** Settings' "Keep pictures offline": every picture the games show, kept on this device (pics.js), and how far it's got. */
function picturesPart(sheet) {
  const box = document.createElement("div"), status = line("");
  let last = null;
  const say = p => {
    last = p;
    // a page Wikipedia has no image for isn't kept, and isn't counted as kept either: said, so "all kept" is true
    const none = p.none || 0, without = none ? ` ${none} ${none === 1 ? "has" : "have"} no picture on Wikipedia (a question about one names it).` : "";
    status.textContent = !keepingPictures() ? `On this device: every painting, building and place the games show, about ${Math.round(p.total * 0.07)} MB from Wikipedia. Pictures you've seen are kept anyway.`
      : p.checking ? "Checking the pictures kept on this device…"
      : !p.done ? `Keeping pictures offline: ${p.kept} of ${p.total}`
      : p.kept + none >= p.total ? `All ${p.kept} pictures are kept on this device.${without}`
      : `${p.kept} of ${p.total - none} kept: ${p.offline ? "the rest come when there's a connection" : `${p.missing} wouldn't download, tried again next time`}.${without}`;
  };
  const stop = onPictures(say);
  sheet.addEventListener("close", stop, { once: true });
  box.append(toggle("Keep pictures offline", keepingPictures(), on => {
    setKeepingPictures(on);
    if (last) say({ ...last, done: !on, checking: on });          // at once: the first count comes once Wikipedia answers
    if (on) keepPicturesOffline();
  }), status);
  import("./pics-list.js").then(({ PICTURES }) => {
    say({ kept: 0, total: PICTURES.length, missing: 0, none: 0, done: false, checking: true });
    if (keepingPictures()) keepPicturesOffline();            // where it stands: a quick check when it's all there
  });
  return box;
}
// once it's on, pictures not kept yet (added to the games since, or a download cut short) come down a few seconds
// after a page opens, while there's a connection; a partner's watching frame never downloads
if (!IN_FRAME && keepingPictures() && navigator.onLine) setTimeout(() => keepPicturesOffline(), 5000);
// The games a reset can start over: all but Crates (its run is synced on its own, and it resets its learning in its own
// Settings), Deck (its pile is every game's misses) and Ledger and Almanac (records of the others, not games of their own)
const KEEP_ON_RESET = new Set(["crates", "deck", "ledger", "lexicon"]);
/** Settings' "Start a game over", folded away: a game's name, a confirmation, and every level, save and setting of it
 *  goes, here and on your other devices. The game open in this page starts again at once. The Appendix's games aren't
 *  listed (Korbi, 3 November 2026: it stays out of Random and of this). */
function startOver() {
  const box = document.createElement("details"), grid = document.createElement("div"), note = document.createElement("p");
  box.className = "menu-stages settings-reset";
  box.innerHTML = "<summary>Start a game over</summary>";
  grid.className = "menu-grid";
  note.className = "menu-line";
  note.textContent = "Its levels, stars, saves and settings go, on this device and every other with your solo code. Crates resets its learning in its own Settings.";
  const here = (location.pathname.split("/").pop() || "index.html");
  for (const a of APPS.filter(x => !KEEP_ON_RESET.has(x.id) && !x.party && !x.within && !x.soon && x.sec !== "appendix")) {   // a game's mode goes with the game; the Appendix is set aside
    const b = document.createElement("button");
    b.type = "button"; b.textContent = a.name;
    b.addEventListener("click", async () => {
      if (!(await sure(`Start ${a.name} over? Every level, star, save and setting of it goes, here and on your other devices. This can't be undone.`, { yes: "Start over" }))) return;
      for (const x of grid.children) x.disabled = true;
      await resetGame(a.id);
      if (a.href.split("?")[0].endsWith(here)) { location.reload(); return; }        // the game on screen: it starts again now
      note.textContent = `${a.name} starts over.`;
      for (const x of grid.children) x.disabled = false;
      dispatchEvent(new Event("suite:pulled"));                          // the games screen redraws its tiles
    });
    grid.appendChild(b);
  }
  box.append(grid, note);
  return box;
}

/** The games screen's sections, in order: every game is in one (APPS' sec). The Appendix at the back holds what is set aside for
 *  now: games flagged to leave, or to become an app of their own (README, The Appendix). */
export const SECTIONS = [["knowledge", "Knowledge"], ["courses", "Courses"], ["puzzle", "Puzzles"], ["classics", "Classics"], ["idle", "Idle"], ["board", "Board games"], ["cards", "Cards & dice"], ["party", "Party"], ["appendix", "Appendix"]];
/** A tile's name: a long one (Refinery, Manifest) set closer, a longer one (Undercover) smaller too, to fit its tile. */
export const nameClass = name => `app-name${name.length >= 10 ? " long longer" : name.length >= 8 ? " long" : ""}`;
const tile = (a, current) => `<li class="app-tile" data-id="${a.id}"><a class="app-row${a.id === current ? " cur" : ""}" href="${a.href}"${a.id === current ? ' aria-current="page"' : ""}>
      <span class="app-logo">${a.logo}${a.id === current ? '<i class="app-now" role="img" aria-label="Playing" title="Playing"></i>' : ""}</span><b class="${nameClass(a.name)}">${a.name}</b><small class="app-best" data-best="${a.id}"></small></a>${starButton(a)}</li>`;
const tiles = (apps, current) => SECTIONS.map(([sec, title]) => {
  const list = apps.filter(a => a.sec === sec);
  return list.length ? `<li class="apps-group" data-sec="${sec}"><h3 class="apps-sec">${title}</h3><ul class="apps-grid">${list.map(a => tile(a, current)).join("")}</ul></li>` : "";
}).join("");
const short = n => (n >= 1e6 ? `${(n / 1e6).toFixed(n >= 1e7 ? 0 : 1)}m` : n >= 1e4 ? `${Math.round(n / 1e3)}k` : Number.isInteger(n) ? n.toLocaleString("en-GB") : n.toFixed(2));
/**
 * A tile's line: your figure and your partner's (by initial). A streak, today's time or count, stars, or a best; today's
 * board, puzzle or run first, when either of you has played it (a dash for whoever hasn't): Crates, Slate, Delta, Punt and
 * the other daily games.
 */
function tileText(id, mine, theirs, P) {
  const kind = MARKS[id] || "best", d = today(), clock = n => `${Math.floor(n / 60)}:${String(n % 60).padStart(2, "0")}`;
  // today's comes first: once either of you has played today's board, puzzle or run (Crates, Slate, Delta, Punt and the
  // other daily games), both tiles show how it went, a dash for whoever hasn't
  if (kind === "daily" || kind === "time" || id === "crates") {
    const todayOf = m => (m?.day === d ? (kind === "time" ? m.v : m.today) ?? null : null), a = todayOf(mine), b = todayOf(theirs);
    const show = v => (kind === "time" ? clock(v) : scoreText(id, v));
    if (a != null || b != null) return [`Today ${a != null ? show(a) : "—"}`, theirs ? `${P} ${b != null ? show(b) : "—"}` : ""].filter(Boolean).join(" · ");
    if (kind === "daily") return [mine?.best != null ? `Best ${scoreText(id, mine.best)}` : "", theirs?.best != null ? `${P} ${scoreText(id, theirs.best)}` : ""].filter(Boolean).join(" · ");
  }
  const today_ = m => (kind === "time" || kind === "count" || kind === "guesses" ? m?.day === d : true) ? m : null;    // a day's figure is today's or nothing
  const show = m => (kind === "time" ? clock(m.v) : kind === "stars" ? `★ ${m.v}` : kind === "best" || kind === "guesses" ? scoreText(id, m.v) : String(m.v));
  const lead = { streak: "Streak", time: "Today", count: "Today", guesses: "Today", wins: "Wins", stars: "", best: "Best" }[kind];
  const a = today_(mine), b = today_(theirs);
  return [a ? `${lead ? `${lead} ` : ""}${show(a)}` : "", b ? `${P} ${show(b)}` : ""].filter(Boolean).join(" · ");
}
/**
 * A game's score as its tile shows it: most as a number, a return a question (Punt's) as a signed percentage, 0.41 as
 * +41%, and the guesses a code or a word took out of the rows there were (Assay's 3/6, Bulls' 4/10; ✕ when it wasn't
 * found: Assay counts that as a guess past the last row, Bulls as 0).
 */
const scoreText = (id, n) => {
  const app = APPS.find(a => a.id === id), kind = app?.score;
  if (kind === "return") return `${n > 0 ? "+" : n < 0 ? "−" : ""}${Math.round(Math.abs(n) * 100)}%`;
  if (kind === "board") { const t = 99999 - (n % 100000); return `${Math.floor(n / 100000)}/8 in ${Math.floor(t / 60)}:${String(t % 60).padStart(2, "0")}`; }   // Crates: points, then time
  if (kind === "guesses") return `${n >= 1 && n <= app.rows ? n : "✕"}/${app.rows}`;
  return short(n);
};
// the head's icons: one person (your solo code), two (your partner code), settings, refresh (update), and close
const ICON = {
  solo: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.6"/><path d="M4.5 20c.6-4 3.6-6.2 7.5-6.2s6.9 2.2 7.5 6.2"/></svg>',
  duo: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="8.5" cy="8.5" r="3.1"/><path d="M2.5 19.5c.5-3.4 2.9-5.3 6-5.3s5.5 1.9 6 5.3"/><circle cx="16.5" cy="8" r="2.7"/><path d="M15.2 13.9c3.3-.3 5.7 1.5 6.3 5.1"/></svg>',
  update: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19.5 12a7.5 7.5 0 1 1-2.2-5.3"/><path d="M19.8 4.2v4.6h-4.6"/></svg>',
  close: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>',
  settings: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h10M18 7h2M4 17h4M12 17h8"/><circle cx="16" cy="7" r="2.2"/><circle cx="10" cy="17" r="2.2"/></svg>',
  gear: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9.95 5.31L10.37 2.74L13.63 2.74L14.05 5.31A7.0 7.0 0 0 1 16.77 6.88L19.20 5.96L20.83 8.79L18.82 10.43A7.0 7.0 0 0 1 18.82 13.57L20.83 15.21L19.20 18.04L16.77 17.12A7.0 7.0 0 0 1 14.05 18.69L13.63 21.26L10.37 21.26L9.95 18.69A7.0 7.0 0 0 1 7.23 17.12L4.80 18.04L3.17 15.21L5.18 13.57A7.0 7.0 0 0 1 5.18 10.43L3.17 8.79L4.80 5.96L7.23 6.88A7.0 7.0 0 0 1 9.95 5.31Z"/><circle cx="12" cy="12" r="2.6"/></svg>',
  tick: '<svg class="code-tick" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>',
};
/**
 * The games screen's head, in one line: your solo code (one person: every device with it is in the same state in every
 * game) and your partner code (two people), then what your partner is playing. Tapping a code copies this page's link
 * with it (solo: both codes, for your other devices; partner: the partner code, for your partner); holding a code (or
 * tapping it while there's none) lets you type one: one nobody has yet starts fresh, so you can pick your own. Tapping
 * your partner's line opens the partner sheet. Each tile shows its best, your partner's, and your duo record.
 */
const GAME_NAME = id => APPS.find(a => a.id === (id === "slate" ? "glyph" : id))?.name || id;
function bindCodes(dlg) {
  const head = dlg.querySelector("[data-codes]");
  let partner = null, theirs = {}, theirMarks = {}, theirName = "", duoRecords = {};
  const here = (location.pathname.split("/").pop() || "index.html").replace(/\.html$/, "").replace(/^index$|^$/, "");   // "" at home: no game open
  const status = p => (p ? `${(p.name || "Partner").split(" ")[0]} · ${!p.online ? "offline" : !p.game ? "choosing a game" : `${GAME_NAME(p.game)}${p.mode === "duo" ? " together" : p.mode === "watch" ? " (watching)" : ""}`}` : "not here yet");
  const draw = () => {
    const solo = soloCode(), duo = duoCode();
    // a tick: syncing (solo) or linked (partner); the codes themselves are in the links a tap copies, and in the box a hold opens
    head.innerHTML = `<button class="code-chip${solo ? " set" : ""}" type="button" data-solo aria-label="Your solo code${solo ? ` ${solo}, syncing: tap to copy its link, hold to change it` : ": tap to set it"}">${ICON.solo}${solo ? ICON.tick : "<b>+</b>"}</button>
      <button class="code-chip${duo ? " set" : ""}" type="button" data-duo aria-label="Your partner code${duo ? ` ${duo}, linked: tap to copy its link, hold to change it` : ": tap to set it"}">${ICON.duo}${duo ? ICON.tick : "<b>+</b>"}</button>
      ${duo ? `<button class="partner-line${partner?.online ? " on" : ""}" type="button" data-pair></button>` : ""}`;
    if (duo) head.querySelector("[data-pair]").textContent = status(partner);
    for (const el of dlg.querySelectorAll("[data-best]")) {
      const id = el.dataset.best, mine = bestOf(id), them = theirs[id], a = el.closest("a"), app = APPS.find(x => x.id === id);
      // a game whose daily you haven't played today opens on it: the tile's the way in to today's puzzle or run
      if (a && app && a.getAttribute("aria-current") !== "page") a.setAttribute("href", dailyDue(id) ? `${app.href}#today` : app.href);
      // three scores: your solo best, your partner's (by initial), and the pair's duo record (duo-records.js), a team's
      // best in the game's own terms: a time (Slate, Delta), restows (Stow, the fewest), else points or the pot (Punt's
      // solo best is a return, which its pot isn't: 1,240 showed as +124000%)
      const time = n => `${Math.floor(n / 60)}:${String(n % 60).padStart(2, "0")}`;
      // a pair's best together, as the game counts it (an entry's team: a time, a share of everything to find, or as its score)
      const team = APPS.find(a => a.id === id)?.team;
      const teamBest = n => (id === "stow" ? `${n} restow${n === 1 ? "" : "s"}` : id === "glyph" || id === "delta" || team === "time" ? time(n) : team === "pct" ? `${n}%` : id === "punt" ? short(n) : scoreText(id, n));
      const duoText = duo ? duoLine(duoRecords[id === "glyph" ? "slate" : id], teamBest) : "";
      // your figure and your partner's (a partner on an older version sends only a best)
      const theirMark = duo ? theirMarks[id] || (them != null ? { kind: MARKS[id] === "daily" ? "daily" : "best", v: them, best: them } : null) : null;
      el.textContent = [tileText(id, markOf(id), theirMark, (theirName || "P")[0]), duoText].filter(Boolean).join(" · ");
    }
  };
  // typing a code: an existing one is followed (solo) or joined (partner); a new one starts fresh, from here
  const editSolo = async () => {
    const now = soloCode();
    const typedCode = await typed(`Your solo code${now ? ` is ${now}` : ""}. Type 8 letters: a code you use on another device, or a new one of your own to start here${now ? "" : " (empty: a random one)"}:`);
    if (typedCode === null) return;
    const code = cleanCode(typedCode);
    if (!code && !now) startSolo();
    else if (code.length === 8 && code !== now) await chooseSolo(code);
    else { if (code) await notice("A solo code is 8 letters."); return; }
    location.reload();
  };
  const editDuo = async () => {
    const now = duoCode();
    const typedCode = await typed(`Your partner code${now ? ` is ${now}` : ""}. Type 4 letters: your partner's, or a new one of your own for them to type${now ? "" : " (empty: a random one)"}:`);
    if (typedCode === null) return;
    const code = cleanCode(typedCode);
    if (!code && !now) link();
    else if (code.length === 4 && code !== now) link(code);
    else { if (code) await notice("A partner code is 4 letters."); return; }
    location.reload();
  };
  const copy = async (kind, chip) => {
    const url = codesLink(kind), was = chip.innerHTML;
    try { await navigator.clipboard.writeText(url); chip.innerHTML = `${ICON[kind]}<b>Copied</b>`; } catch { await typed("Copy this link:", { value: url, yes: "Done" }); return; }
    setTimeout(() => { chip.innerHTML = was; }, 1200);
  };
  // tap copies the link, hold types a code (a code that isn't set yet is typed on a tap)
  let held = null, heldFired = false;
  head.addEventListener("pointerdown", e => {
    const chip = e.target.closest("[data-solo], [data-duo]");
    if (!chip) return;
    heldFired = false;
    held = setTimeout(() => { heldFired = true; (chip.matches("[data-solo]") ? editSolo : editDuo)(); }, 550);
  });
  const release = () => clearTimeout(held);
  head.addEventListener("pointerup", release);
  head.addEventListener("pointerleave", release);
  head.addEventListener("contextmenu", e => { if (e.target.closest("[data-solo], [data-duo]")) e.preventDefault(); });
  // the partner sheet: link, ask to play together, back to solo, unlink
  const sheet = document.createElement("dialog");
  sheet.className = "pair-sheet";
  dlg.appendChild(sheet);
  const openSheet = () => {
    const duo = duoCode(), inDuo = new URLSearchParams(location.search).has("room");
    sheet.replaceChildren();
    const x = document.createElement("button");
    x.className = "icon-btn sheet-x"; x.type = "button"; x.setAttribute("aria-label", "Close"); x.innerHTML = ICON.close;
    x.addEventListener("click", () => sheet.close());
    sheet.appendChild(x);
    const add = (tag, cls, text) => { const n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; sheet.appendChild(n); return n; };
    const button = (text, fn, cls = "btn wide") => { const b = add("button", cls, text); b.type = "button"; b.addEventListener("click", fn); return b; };
    add("h3", null, "Your partner");
    {
      const said = status(partner);
      add("p", "stats", `Code ${duo}. ${said[0].toUpperCase()}${said.slice(1)}.`);
      const them = partner?.online && partner.game, mine = here, first = (partner?.name || "them").split(" ")[0];
      const askFor = game => async () => {
        sheet.close();
        const b = head.querySelector("[data-pair] em");
        if (b) b.textContent = `Asking to play ${GAME_NAME(game)}…`;
        const answer = await ask(game);
        if (answer === "yes") return;                    // ask() is taking this page to the table
        draw(); await notice(answer === "no" ? "Not now, they said." : "No answer.");
      };
      if (them && partner.mode === "solo") button(`Watch ${first}'s ${GAME_NAME(them)}`, () => { location.href = watchHref(them); }, "btn primary wide");
      if (them && DUO_GAMES[them] && partner.mode === "solo") button(`Ask to play ${GAME_NAME(them)} together`, askFor(them));
      // they're at your table and you aren't (you went back to solo, or came in on another device): sit down again
      if (them && DUO_GAMES[them] && partner.mode === "duo" && !(inDuo && mine === them)) button(`Join ${first} in ${GAME_NAME(them)}`, () => { location.href = duoHref(them); }, "btn primary wide");
      if (partner?.online && DUO_GAMES[mine] && mine !== them && !inDuo) button(`Ask to play ${GAME_NAME(mine)} together`, askFor(mine));   // only someone who's here can say Play
      if (inDuo) button("Back to solo", () => { location.href = soloHref(); });
      button("Unlink", async () => { if (await sure("Unlink from your partner on all your devices?", { yes: "Unlink" })) { unlink(); location.reload(); } }, "link");
    }
    sheet.showModal();
  };
  head.addEventListener("click", e => {
    if (heldFired) { heldFired = false; return; }
    const solo = e.target.closest("[data-solo]"), duo = e.target.closest("[data-duo]");
    if (solo) { if (soloCode()) copy("solo", solo); else editSolo(); }
    if (duo) { if (duoCode()) copy("duo", duo); else editDuo(); }
    if (e.target.closest("[data-pair]")) openSheet();
  });
  draw();
  // your other devices' results, once they've come in: drawn here, and passed on to your partner's tiles
  addEventListener("suite:pulled", () => { draw(); if (duoCode() && !IN_FRAME) shareBests(APPS.filter(a => !a.soon).map(a => a.id)).catch(() => {}); });
  if (duoCode() && !IN_FRAME) {
    shareBests(APPS.filter(a => !a.soon).map(a => a.id)).catch(() => {});
    watchPartner(p => { partner = p; draw(); }).catch(() => {});
    watchBests((bests, name, marks) => { theirs = bests; theirName = name; theirMarks = marks || {}; draw(); }).catch(() => {});
    watchDuoRecords(r => { duoRecords = r; draw(); }).catch(() => {});
  }
  return draw;
}

export function bindSwitcher(button, current) {
  const dlg = document.createElement("dialog");
  // A full screen of games, a tile each with its logo and name, every game on it: the tiles scroll in their own box when
  // they don't all fit, the screen around them never does. Settings (a gear in Codex, sliders in the other themes)
  // and refresh at the top right.
  dlg.className = "apps";
  dlg.setAttribute("aria-label", "Games");
  dlg.innerHTML = `<div class="apps-inner"><h2 class="apps-brand" aria-label="Codex">${BRAND}${NAME}</h2><div class="pick-head"><div class="codes" data-codes></div><span class="apps-actions">
      <button class="icon-btn" type="button" data-settings title="Settings" aria-label="Settings" aria-haspopup="dialog">${theme() === "deco" ? ICON.gear : ICON.settings}</button>
      <button class="icon-btn" type="button" data-update title="Load the newest version (keeps your progress)" aria-label="Update">${ICON.update}</button>
      <button class="icon-btn" type="button" data-close aria-label="Close">${ICON.close}</button></span></div>
    <p class="menu-line apps-note" role="status" hidden></p>
    <div class="rd-rows" data-rows${bannerOn() ? "" : " hidden"}><div class="rd-row"><div class="rd-cell" data-deck></div><div class="rd-cell" data-random></div><div class="rd-cell" data-choose></div></div></div>
    <ul class="apps-list">${tiles(APPS, current)}</ul></div>`;
  document.body.appendChild(dlg);
  dlg.querySelector("[data-close]").addEventListener("click", () => dlg.close());
  dlg.querySelector("[data-settings]").addEventListener("click", () => openSettings(dlg));
  // the list's edges fade where there are more tiles past them, so a phone that shows five rows says there's a sixth
  const list = dlg.querySelector(".apps-list");
  bindFind({ dlg, list, apps: APPS, sections: SECTIONS });        // the stars, and the search and filter that come down from the list's top
  const edges = () => {
    list.classList.toggle("more-above", list.scrollTop > 1);
    list.classList.toggle("more-below", list.scrollTop + list.clientHeight < list.scrollHeight - 1);
  };
  list.addEventListener("scroll", edges, { passive: true });
  new ResizeObserver(edges).observe(list);                       // it opens, the screen turns
  // each time the screen opens, the game you're in is in view: it may be far down the list
  new MutationObserver(() => { if (dlg.open) dlg.querySelector(".app-row.cur")?.scrollIntoView({ block: "nearest" }); })
    .observe(dlg, { attributes: true, attributeFilter: ["open"] });
  // after an update the app reloads: open the games screen again, where Update was pressed
  try { if (sessionStorage.getItem("crates:games")) { sessionStorage.removeItem("crates:games"); dlg.showModal(); } } catch { /* private mode */ }
  // Update says what it finds in a line under the head (up to date, offline); a newer version downloads under the
  // mark, over the page, which then reloads onto it (pwa.js)
  const update = dlg.querySelector("[data-update]"), note = dlg.querySelector(".apps-note");
  const tell = (words, waiting = false) => { note.replaceChildren(...(waiting ? [waitMark()] : []), words); note.hidden = false; };
  dlg.addEventListener("close", () => { note.hidden = true; });
  update.addEventListener("click", async () => {
    update.disabled = true;
    update.classList.add("spin");                      // turning while it checks
    if (await hardUpdate({ tell, before: () => dlg.close() })) return;
    update.classList.remove("spin");
    update.disabled = false;
    if (!dlg.open) dlg.showModal();                    // a download that came to nothing: back where Update was pressed, the line saying why
  });
  // the game you're in: its tile just closes the screen of games
  dlg.querySelectorAll("a.app-row.cur").forEach(row => row.addEventListener("click", e => { e.preventDefault(); dlg.close(); }));
  APPS.forEach(a => {
    if (a.id === current) return;
    // a tile always opens the game solo: a duo match only starts when your partner says Play. Its link as it stands when
    // tapped: today's (#today) while that's still to play
    dlg.querySelectorAll(`.app-row[href="${a.href}"]`).forEach(row => row.addEventListener("click", e => { e.preventDefault(); location.href = row.getAttribute("href"); }));
  });
  const redraw = bindCodes(dlg);
  button.addEventListener("click", () => { redraw(); dlg.showModal(); });
  // inside every game, a small line in the title: what your partner is playing (green while they're online)
  if (duoCode() && !IN_FRAME) {
    const pill = document.createElement("small");
    pill.className = "partner-pill";
    button.appendChild(pill);
    watchPartner(p => {
      pill.textContent = p ? `${(p.name || "Partner").split(" ")[0]} · ${p.online ? `${GAME_NAME(p.game)}${p.mode === "duo" ? " ×2" : ""}` : "away"}` : "";
      pill.classList.toggle("on", !!p?.online);
    }).catch(() => {});
  }
  // Random (random.js): its row under the head, and random mode playing on in this game, or ended by your coming here
  bindRandom({ games: APPS, sections: SECTIONS, row: dlg.querySelector("[data-random]"), title: current ? button : null, current });
  bindDeckRow({ row: dlg.querySelector("[data-deck]"), host: dlg });
  bindChoose({ cell: dlg.querySelector("[data-choose]"), host: dlg });
}
